function updateHUD(e,t){const n={devices:"Equipment Preparation",ecg:"ECG Monitoring",repair:"Defibrillator Repair",stabilize:"Resuscitation"},i=document.getElementById("hud-stage"),o=document.getElementById("progress-bar");if(i&&(i.textContent=`\n        Stage ${e+1}/4 -\n        ${n[t]}\n        `),o){const t=(e+1)/4*100;o.style.width=t+"%"}updatePatientHUD(),renderMissionLog()}